insert into public.flashcards (id, deck, domain, objective, front, back) values
('f4-081','core',4,'4.1',$$What is a deauthentication attack against Wi-Fi and its defense?$$,$$Sending spoofed 802.11 deauth frames to forcibly disconnect clients, often to force reconnection to an evil twin; Protected Management Frames (802.11w) and WPA3 defend against forged deauth frames.$$),
('f4-082','core',4,'4.1',$$What is geofencing as a mobile security control?$$,$$Restricting app functionality or data access based on the device's physical location - e.g., disabling corporate data access outside an approved country or campus.$$),
('f4-083','core',4,'4.1',$$What is a jailbroken/rooted device risk to MDM enrollment?$$,$$Removing OS-level restrictions defeats the sandboxing and integrity checks MDM relies on; most MDM policies detect and block enrollment or wipe jailbroken/rooted devices.$$),
('f4-084','core',4,'4.2',$$What is a CMDB (Configuration Management Database)?$$,$$A repository tracking IT assets and their relationships/configurations - underpins accurate vulnerability scoping, change impact analysis, and incident response.$$),
('f4-085','core',4,'4.2',$$RFID vs barcode asset tracking - trade-off?$$,$$Barcode: cheap, requires line-of-sight scanning. RFID: can be read in bulk/at a distance without line-of-sight, costs more per tag - both feed inventory accuracy.$$),
('f4-086','core',4,'4.3',$$What is responsible/coordinated vulnerability disclosure?$$,$$A researcher privately reports a flaw to the vendor, giving them time to patch before public disclosure - balances user safety (patch first) against accountability (eventual disclosure).$$),
('f4-087','core',4,'4.3',$$What is a disclosure deadline/embargo in vulnerability handling?$$,$$An agreed timeframe (commonly 90 days) after which the researcher may publish details regardless of whether a patch exists, pressuring vendors to act.$$),
('f4-088','core',4,'4.3',$$What is "Patch Tuesday" and why does batching patches matter?$$,$$Microsoft's monthly scheduled patch release; predictable cadence lets organizations plan testing/deployment windows, versus ad hoc patches disrupting operations unpredictably.$$),
('f4-089','core',4,'4.4',$$What is a threat intelligence platform (TIP)?$$,$$Aggregates, correlates, and operationalizes threat intel feeds (IOCs, TTPs) so detections and blocklists stay current automatically rather than manual feed review.$$),
('f4-090','core',4,'4.4',$$What tension exists between log retention length and cost/privacy?$$,$$Longer retention aids forensics on slow-burn intrusions but increases storage cost and the privacy/breach-impact surface of stored data - retention policy must balance both.$$),
('f4-091','core',4,'4.4',$$What is dashboarding in a SIEM used for beyond alerting?$$,$$Visualizing trends and posture for different audiences (SOC operational view vs executive summary) - turns raw log volume into decision-usable information.$$),
('f4-092','core',4,'4.4',$$What is a watchlist in monitoring?$$,$$A curated list of high-risk entities (IPs, accounts, hashes) that trigger elevated scrutiny or automatic alerts whenever they appear in logs.$$),
('f4-093','core',4,'4.5',$$Why is inline IPS blocking mode riskier to deploy than IDS alert-only mode?$$,$$A false positive in blocking mode drops legitimate traffic (potential outage); alert-only mode only generates a notification, so new signatures are often tested in alert mode before enabling blocking.$$),
('f4-094','core',4,'4.5',$$What is email sandboxing (detonation) in a mail gateway?$$,$$Attachments/links are opened in an isolated environment before delivery to observe behavior, catching malware that static scanning alone would miss.$$),
('f4-095','core',4,'4.5',$$Why does DLP require tuning after deployment?$$,$$Overly broad rules generate false positives that block legitimate business activity (alert fatigue, user frustration); tuning narrows detection to real sensitive-data patterns.$$),
('f4-096','core',4,'4.5',$$What is conditional access as an enterprise capability?$$,$$Access decisions that adapt to context (device compliance, location, risk score) in real time - e.g., requiring step-up MFA for an unfamiliar login location.$$),
('f4-097','core',4,'4.6',$$What is Just-In-Time (JIT) access combined with an approval workflow?$$,$$A user requests elevated access for a specific task; an approver grants it for a limited window, and it expires automatically - reduces standing privilege while keeping a human in the loop.$$),
('f4-098','core',4,'4.6',$$What does PAM session recording capture and why?$$,$$Video/keystroke recording of privileged sessions (what commands were run, what was viewed) - provides accountability and forensic evidence for the highest-risk accounts.$$),
('f4-099','core',4,'4.6',$$What is step-up authentication?$$,$$Requiring an additional authentication factor only when a riskier action is attempted (e.g., changing a password or making a large transfer), not for every request.$$),
('f4-100','core',4,'4.6',$$What is identity federation's trust anchor?$$,$$The IdP's signing key/certificate - the SP trusts assertions because they are cryptographically signed by an IdP it has explicitly configured to trust.$$),
('f4-101','core',4,'4.7',$$What is a SOAR playbook, with an example trigger/action?$$,$$A predefined automated workflow: e.g., trigger = phishing report submitted; actions = pull the email from all mailboxes, block sender domain, isolate hosts that clicked, open a ticket.$$),
('f4-102','core',4,'4.7',$$What security risk does over-automation introduce?$$,$$A flawed playbook executes its mistake at machine speed across every matching case before a human notices - automation multiplies both good and bad outcomes.$$),
('f4-103','core',4,'4.8',$$What is network forensics and what does it recover that host forensics can't?$$,$$Reconstructing attacker activity from captured network traffic (PCAP, flow data) - reveals what was communicated across the wire even if the host itself was wiped.$$),
('f4-104','core',4,'4.8',$$What makes a good tabletop exercise scenario?$$,$$Realistic, specific to the organization's actual risks, with enough ambiguity to force real decision-making - not so scripted that it just rehearses a known answer.$$),
('f4-105','core',4,'4.8',$$What is "preservation of evidence" as distinct from "collection"?$$,$$Collection gathers evidence; preservation ensures it isn't altered afterward (hashing, write-blockers, secure storage) - both are required for evidence to remain usable.$$);
insert into public.questions (id, domain, objective, qtype, difficulty, stem, choices, answer, explanation) values
('q4-071',4,'4.1','mcq',2,$q$Users near a conference room repeatedly get disconnected from Wi-Fi moments before an identical-looking rogue SSID appears strong nearby. What attack combination is occurring?$q$,$q$["Deauthentication attack forcing reconnection to an evil twin","DHCP starvation","VLAN hopping","MAC flooding"]$q$::jsonb,'0'::jsonb,$q$Forcing disconnection via deauth frames, then luring victims to a look-alike rogue AP (evil twin), is a classic combined wireless attack for credential capture. The other options describe unrelated network attacks.$q$),
('q4-072',4,'4.1','mcq',2,$q$Which WPA3/802.11 feature specifically defends against forged deauthentication frames?$q$,$q$["SAE handshake","Protected Management Frames (802.11w)","WEP","Open authentication"]$q$::jsonb,'1'::jsonb,$q$Protected Management Frames cryptographically protect management frames, including deauth/disassociation, preventing forged disconnects. SAE hardens the initial handshake against offline attacks - a related but different protection.$q$),
('q4-073',4,'4.1','mcq',2,$q$A company wants corporate app data to become inaccessible automatically whenever a device leaves an approved country. Which mobile control fits?$q$,$q$["Geofencing","Containerization only","Bluetooth pairing restriction","SSID hiding"]$q$::jsonb,'0'::jsonb,$q$Geofencing ties data/app access to physical location, restricting it outside approved boundaries. Containerization separates work/personal data but doesn't itself enforce location.$q$),
('q4-074',4,'4.1','mcq',2,$q$An MDM policy automatically blocks enrollment of any device it detects as jailbroken or rooted. Why?$q$,$q$["Jailbreaking improves security","Jailbreaking removes OS-level restrictions that MDM sandboxing and integrity checks rely on, defeating enforcement","Jailbroken devices cannot connect to Wi-Fi","MDM cannot detect jailbreaking"]$q$::jsonb,'1'::jsonb,$q$Jailbreaking/rooting removes the OS protections MDM depends on to sandbox apps and verify integrity, so a compromised device could bypass policy entirely - hence the block.$q$),
('q4-075',4,'4.1','mcq',1,$q$Which wireless authentication mode issues per-user, individually revocable credentials via RADIUS?$q$,$q$["WPA2/WPA3-Personal","WPA2/WPA3-Enterprise (802.1X)","WEP","Open network"]$q$::jsonb,'1'::jsonb,$q$Enterprise mode authenticates each user individually through 802.1X/RADIUS, so one departure revokes one account without re-keying everyone else - unlike a shared Personal-mode passphrase.$q$),
('q4-076',4,'4.2','mcq',2,$q$A vulnerability scan finds a critical flaw on a device with no owner, no ticket history, and no record in the asset database. What underlying process failure does this represent?$q$,$q$["Patch management","Asset management / CMDB accuracy","Encryption policy","Change management"]$q$::jsonb,'1'::jsonb,$q$An unknown, untracked device means asset management failed - you can't patch, monitor, or scope what isn't in the inventory. The other processes depend on accurate asset data to function.$q$),
('q4-077',4,'4.2','mcq',2,$q$What is the PRIMARY purpose of a CMDB in incident response?$q$,$q$["Storing marketing materials","Providing accurate asset relationships and ownership so responders can quickly scope what's affected and who to contact","Managing payroll","Hosting the company website"]$q$::jsonb,'1'::jsonb,$q$A CMDB's asset relationships and ownership data let responders rapidly determine blast radius and the right contacts during an incident - critical for fast, accurate scoping.$q$),
('q4-078',4,'4.2','mcq',2,$q$A warehouse needs to inventory hundreds of assets in bulk without individually scanning each one with line-of-sight. Which tracking technology fits best?$q$,$q$["Barcode labels","RFID tags","QR codes only","Manual spreadsheet entry"]$q$::jsonb,'1'::jsonb,$q$RFID tags can be read in bulk and at a distance without requiring line-of-sight scanning, unlike barcodes/QR codes which need to be individually aimed and scanned.$q$),
('q4-079',4,'4.2','mcq',2,$q$Why does inaccurate asset inventory directly weaken vulnerability management?$q$,$q$["It doesn't - vulnerability scanning is independent of inventory","Scanners and analysts can't prioritize or even find flaws on assets nobody knows exist","It only affects billing","It affects only physical security, not vulnerabilities"]$q$::jsonb,'1'::jsonb,$q$You cannot protect, scan, or prioritize remediation for systems that aren't tracked - unknown assets are invisible to the entire vulnerability management lifecycle.$q$),
('q4-080',4,'4.3','mcq',2,$q$A researcher privately reports a critical flaw to a vendor and agrees to withhold public details for 90 days while the vendor develops a patch. What practice is this?$q$,$q$["Full disclosure","Responsible/coordinated disclosure","Bug bounty extortion","Zero-day sale"]$q$::jsonb,'1'::jsonb,$q$Privately reporting and allowing time to patch before publication is responsible (coordinated) disclosure - balancing user safety against eventual public accountability.$q$),
('q4-081',4,'4.3','mcq',2,$q$Why do coordinated disclosure agreements typically include a deadline (e.g., 90 days)?$q$,$q$["To give the vendor unlimited time","To pressure the vendor to patch in a reasonable window, after which the researcher may publish regardless","Deadlines are only symbolic and never enforced","To prevent the vendor from ever patching"]$q$::jsonb,'1'::jsonb,$q$The deadline creates accountability: if the vendor doesn't patch in time, the researcher may publish anyway, motivating timely fixes rather than indefinite silence.$q$),
('q4-082',4,'4.3','mcq',1,$q$What is "Patch Tuesday"?$q$,$q$["A random daily patch release","Microsoft's predictable monthly scheduled patch release, letting organizations plan testing windows","A CompTIA certification exam day","An annual security conference"]$q$::jsonb,'1'::jsonb,$q$Patch Tuesday is Microsoft's regular, scheduled monthly release cadence, which lets IT teams plan testing and deployment windows rather than reacting to unpredictable releases.$q$),
('q4-083',4,'4.3','mcq',2,$q$An organization struggles to plan maintenance windows because updates arrive from a vendor unpredictably throughout the month. Which vendor practice would most directly help this organization plan better?$q$,$q$["Ad hoc daily patches","A predictable scheduled release cadence (like Patch Tuesday)","No patches at all","Patches released only during audits"]$q$::jsonb,'1'::jsonb,$q$A predictable, scheduled cadence lets IT teams pre-plan testing and deployment windows instead of reacting to unpredictable, disruptive releases.$q$),
('q4-084',4,'4.4','mcq',2,$q$A SOC wants its blocklists and detection rules to automatically stay current with the latest known-bad indicators without manual feed review. What should they deploy?$q$,$q$["A threat intelligence platform (TIP) aggregating and operationalizing feeds","A single static blocklist file","A help desk ticketing system","A payroll system"]$q$::jsonb,'0'::jsonb,$q$A TIP ingests, correlates, and operationalizes multiple threat feeds automatically, keeping detections current without manual per-feed review.$q$),
('q4-085',4,'4.4','mcq',2,$q$A compliance requirement mandates logs be retained for 7 years, but storage costs and breach-impact surface both grow with retention length. What must the organization balance?$q$,$q$["Log retention length against storage cost and privacy/breach-impact risk","Firewall throughput against CPU temperature","Payroll against headcount","Nothing - longer retention has no downside"]$q$::jsonb,'0'::jsonb,$q$Longer retention supports compliance and forensics on slow-burn intrusions but increases both cost and the amount of sensitive data exposed if that log store is ever breached - a genuine trade-off to manage.$q$),
('q4-086',4,'4.4','mcq',2,$q$Why does a SIEM provide both an operational SOC dashboard and a separate executive summary view?$q$,$q$["They are identical views by law","Different audiences need different levels of detail - operational responders need granular alerts, executives need trend and risk summaries","Executives never need security information","Dashboards are purely cosmetic"]$q$::jsonb,'1'::jsonb,$q$Analysts need actionable, granular alert detail to respond; leadership needs high-level trends and risk posture to make investment decisions - one raw feed doesn't serve both well.$q$),
('q4-087',4,'4.4','mcq',2,$q$A SIEM maintains a curated list of known-malicious IPs and account names that trigger elevated alerts whenever seen in logs. What is this list called?$q$,$q$["A watchlist","A risk register","A CMDB","A backout plan"]$q$::jsonb,'0'::jsonb,$q$A watchlist flags specific high-risk entities for elevated scrutiny across all monitored logs - distinct from a risk register (business risk tracking) or CMDB (asset inventory).$q$),
('q4-088',4,'4.4','mcq',3,$q$Which pairing correctly matches a monitoring activity to its purpose?$q$,$q$["Log aggregation: centralizing logs from many sources; Alert tuning: reducing false positives to fight alert fatigue","Log aggregation: encrypting logs; Alert tuning: deleting logs","Log aggregation: a firewall function; Alert tuning: a backup function","Log aggregation and alert tuning are the same activity"]$q$::jsonb,'0'::jsonb,$q$Aggregation centralizes logs from disparate sources for analysis; tuning adjusts detection thresholds/rules to reduce false positives - two distinct monitoring activities.$q$),
('q4-089',4,'4.4','mcq',2,$q$What is the FIRST consequence of a SOC receiving far more alerts than analysts can review?$q$,$q$["Improved detection accuracy","Alert fatigue, causing real incidents to be missed among the noise","Faster incident response","Lower staffing costs"]$q$::jsonb,'1'::jsonb,$q$Overwhelming alert volume causes analysts to tune out or miss genuine threats buried in noise - the classic alert-fatigue problem that tuning is meant to solve.$q$),
('q4-090',4,'4.5','mcq',3,$q$Why do security teams typically deploy a brand-new IPS signature in alert-only mode before switching it to blocking mode?$q$,$q$["Alert-only mode is always permanent","A false positive in blocking mode drops legitimate traffic, so teams validate the signature's accuracy against real traffic first","Blocking mode is illegal","Alert-only mode uses less electricity"]$q$::jsonb,'1'::jsonb,$q$Enforcing a new, unproven signature inline risks blocking legitimate traffic on a false positive; validating in alert-only mode first confirms accuracy before accepting that availability risk.$q$),
('q4-091',4,'4.5','mcq',2,$q$An email gateway opens a suspicious attachment in an isolated environment to observe its behavior before deciding whether to deliver it. What capability is this?$q$,$q$["Email sandboxing/detonation","SPF checking","DKIM signing","POP3S retrieval"]$q$::jsonb,'0'::jsonb,$q$Detonating attachments in an isolated sandbox to observe runtime behavior catches malware that signature-only scanning would miss - distinct from sender-authentication checks like SPF/DKIM.$q$),
('q4-092',4,'4.5','mcq',2,$q$Employees complain that a new DLP policy blocks legitimate business emails containing routine order numbers that resemble credit card patterns. What should the security team do?$q$,$q$["Disable DLP entirely","Tune the DLP rule to reduce false positives while still catching real sensitive-data patterns","Ignore the complaints permanently","Block all outbound email"]$q$::jsonb,'1'::jsonb,$q$Tuning narrows detection to genuinely sensitive patterns without abandoning the control entirely - disabling DLP or blocking all mail throws away the protection instead of fixing it.$q$),
('q4-093',4,'4.5','mcq',2,$q$A user normally logging in from New York suddenly attempts a login from a country they've never visited. Which enterprise capability would most likely trigger a step-up MFA challenge in response?$q$,$q$["Conditional access with risk-based policy","A static firewall rule","RAID configuration","DNS filtering alone"]$q$::jsonb,'0'::jsonb,$q$Conditional access evaluates context (location, device, risk signals) in real time and can demand additional verification when something looks anomalous, unlike a static rule.$q$),
('q4-094',4,'4.5','mcq',2,$q$Which combination BEST describes defense-in-depth for inbound email threats?$q$,$q$["SPF/DKIM/DMARC authentication, gateway content filtering, and sandboxing attachments together","Relying on SPF alone","Relying on user judgment alone","Disabling the spam filter for convenience"]$q$::jsonb,'0'::jsonb,$q$Layering sender authentication, content filtering, and behavioral sandboxing covers different threat types (spoofing, known-bad content, and novel malware) that no single control catches alone.$q$),
('q4-095',4,'4.5','mcq',2,$q$What is the security purpose of UEBA flagging a user downloading 50x their normal data volume overnight?$q$,$q$["To improve download speed","To detect anomalous behavior that could indicate a compromised account or insider exfiltration","To bill the user for bandwidth","To reset their password automatically with no alert"]$q$::jsonb,'1'::jsonb,$q$UEBA baselines normal per-user behavior and flags large deviations - a massive off-hours download spike is a textbook indicator worth investigating for compromise or exfiltration.$q$),
('q4-096',4,'4.5','mcq',2,$q$Which capability enforces that only devices meeting a minimum patch level and running EDR may access sensitive internal applications, regardless of valid user credentials?$q$,$q$["Conditional/device-compliance-based access control","A basic username/password login","DNS filtering","Port security"]$q$::jsonb,'0'::jsonb,$q$Device-compliance-based conditional access adds a device-posture requirement on top of valid credentials, blocking access from non-compliant devices even with correct login details.$q$),
('q4-097',4,'4.6','mcq',2,$q$An engineer requests temporary admin rights for a two-hour maintenance task; a manager must approve the request before it's granted, and it expires automatically afterward. What combination of concepts is this?$q$,$q$["Just-in-time access with an approval workflow","Standing privileged access","Federation","Password vaulting alone"]$q$::jsonb,'0'::jsonb,$q$JIT access scoped to a task and time window, gated by human approval, is the modern alternative to standing (always-on) privileged access.$q$),
('q4-098',4,'4.6','mcq',2,$q$Why does PAM software record privileged sessions (keystrokes/video)?$q$,$q$["To slow down administrators","To provide accountability and forensic evidence for the highest-risk accounts, in case of misuse or compromise","To replace passwords entirely","To reduce storage costs"]$q$::jsonb,'1'::jsonb,$q$Session recording creates an auditable record of exactly what a privileged session did - essential accountability and evidence for the accounts capable of the most damage.$q$),
('q4-099',4,'4.6','mcq',2,$q$A banking app requires only a password to view account balances but demands a fresh MFA prompt before authorizing a wire transfer. What is this pattern called?$q$,$q$["Step-up authentication","Federation","Least privilege","Attestation"]$q$::jsonb,'0'::jsonb,$q$Step-up authentication adds a stronger factor only for higher-risk actions, balancing convenience for low-risk activity against security for sensitive ones.$q$),
('q4-100',4,'4.6','mcq',3,$q$In SAML federation, why does the Service Provider trust an assertion it receives from the Identity Provider?$q$,$q$["Because the user typed a password into the SP","Because the assertion is cryptographically signed by an IdP the SP has been explicitly configured to trust","Because all assertions are trusted by default","Because the SP calls the user to verify"]$q$::jsonb,'1'::jsonb,$q$The SP validates the IdP's digital signature on the assertion against a pre-configured trust relationship - the password never reaches the SP at all.$q$),
('q4-101',4,'4.6','mcq',2,$q$Which practice most directly prevents privilege creep as employees change roles over several years?$q$,$q$["Periodic access attestation/recertification","One-time provisioning at hire only","Never reviewing access after initial grant","Disabling MFA"]$q$::jsonb,'0'::jsonb,$q$Recurring attestation forces owners to review and revoke access that's no longer justified as roles change - without it, permissions only accumulate over time.$q$),
('q4-102',4,'4.6','mcq',2,$q$What does "ephemeral credentials" mean in the context of privileged access management?$q$,$q$["Credentials that are generated per-session and expire automatically, leaving nothing standing to steal","Credentials that never expire","Credentials shared across the whole team","Credentials stored in plaintext for convenience"]$q$::jsonb,'0'::jsonb,$q$Ephemeral credentials exist only for the session that needs them and vanish afterward, eliminating standing secrets an attacker could steal and reuse later.$q$),
('q4-103',4,'4.6','mcq',3,$q$Which access control decision would MOST likely rely on ABAC rather than simple RBAC?$q$,$q$["Granting all 'Finance' role members identical access regardless of context","Granting access only if the user is in Finance AND the device is compliant AND the request occurs during business hours","Granting access to anyone with a valid password","Granting access based solely on job title"]$q$::jsonb,'1'::jsonb,$q$Combining multiple contextual attributes (role, device posture, time) in one policy is the natural fit for ABAC; RBAC alone maps permissions to a role without evaluating that many simultaneous conditions.$q$),
('q4-104',4,'4.7','mcq',2,$q$A SOAR playbook triggers on "phishing report submitted" and automatically pulls the email from all mailboxes, blocks the sender domain, and opens a ticket. What is the value of this over a manual process?$q$,$q$["Consistent, immediate execution at machine speed instead of relying on an analyst to remember every step","It requires no initial human report","It replaces the need for any detection tooling","It guarantees zero false positives forever"]$q$::jsonb,'0'::jsonb,$q$Automation guarantees the same complete response every time, immediately, without depending on an individual analyst's memory or availability at that moment.$q$),
('q4-105',4,'4.7','mcq',3,$q$A flawed SOAR playbook mistakenly isolates every host matching a broad, incorrect condition, causing a company-wide outage within minutes. What risk does this illustrate?$q$,$q$["Automation has no risks","Automation executes mistakes at machine speed across every matching case before a human can intervene","This could only happen with manual processes","SOAR platforms cannot cause outages"]$q$::jsonb,'1'::jsonb,$q$A broken automated workflow applies its error everywhere it matches, instantly and at scale - the reason automation risks (single point of failure, complexity) are explicitly part of the exam objective.$q$),
('q4-106',4,'4.7','mcq',2,$q$Which automation use case directly supports the identity lifecycle discussed in objective 4.6?$q$,$q$["Automated user provisioning and deprovisioning tied to HR system events","Automated backup encryption","Automated firewall rule review only","Automated printer queue management"]$q$::jsonb,'0'::jsonb,$q$Tying account creation/removal to HR events (hire/termination) automates the identity lifecycle precisely, closing the gap where manual offboarding is forgotten.$q$),
('q4-107',4,'4.8','mcq',2,$q$An attacker wipes a compromised host's disk before responders arrive, but investigators still recover evidence of the intrusion from captured traffic logs. What discipline made this possible?$q$,$q$["Network forensics using PCAP/flow data captured independently of the host","Disk forensics only","Cloud billing analysis","Password policy review"]$q$::jsonb,'0'::jsonb,$q$Network forensics reconstructs activity from traffic captured elsewhere on the network, surviving even a fully wiped endpoint - evidence disk forensics alone couldn't recover.$q$),
('q4-108',4,'4.8','mcq',2,$q$What distinguishes evidence PRESERVATION from evidence COLLECTION?$q$,$q$["They are the same activity","Collection gathers evidence; preservation ensures it isn't altered afterward via hashing, write-blockers, and secure storage","Preservation happens before collection","Preservation only applies to paper documents"]$q$::jsonb,'1'::jsonb,$q$Collection is the act of gathering evidence; preservation is the ongoing discipline of keeping it unaltered afterward - both are required for the evidence to remain trustworthy and usable.$q$),
('q4-109',4,'4.8','mcq',3,$q$Which quality makes a tabletop exercise scenario effective rather than a rehearsed formality?$q$,$q$["It is scripted so every answer is obvious in advance","It is realistic to the organization's actual risks and ambiguous enough to force genuine decision-making","It never involves any decision-making","It is identical every year with no variation"]$q$::jsonb,'1'::jsonb,$q$A good scenario mirrors real organizational risk and includes enough uncertainty that participants must actually reason through decisions, rather than reciting a known script.$q$),
('q4-110',4,'4.8','mcq',2,$q$A compromised host's RAM is captured before power-down, followed by a verified disk image. What forensic principle governed the ORDER of these two actions?$q$,$q$["Alphabetical order","Order of volatility - most volatile evidence (RAM) is collected before less volatile evidence (disk)","Cost order - cheapest evidence first","Random order - it doesn't matter"]$q$::jsonb,'1'::jsonb,$q$RAM contents vanish at power-off, while disk data persists; order of volatility dictates collecting the most fragile evidence first to avoid losing it.$q$),
('q4-111',4,'4.8','mcq',2,$q$Why is a blameless post-incident review more effective at improving security than one focused on assigning fault?$q$,$q$["Blame has no downsides ever","Fear of blame causes people to hide details, so blameless review surfaces the honest information needed to find the real root cause","Blameless reviews are legally required in all cases","Assigning blame always improves morale"]$q$::jsonb,'1'::jsonb,$q$People under threat of blame omit or distort details, hiding the actual root cause; a blameless approach gets honest input, which is what genuinely prevents recurrence.$q$),
('q4-112',4,'4.8','mcq',2,$q$What is the purpose of documenting chain of custody even for evidence that will never go to court?$q$,$q$["It has no purpose if litigation isn't expected","It preserves the integrity and credibility of findings for any future audit, investigation, or legal need that may arise later","Only law enforcement needs chain of custody","Chain of custody is optional paperwork with no real function"]$q$::jsonb,'1'::jsonb,$q$Litigation needs aren't always foreseeable at the time of an incident; maintaining chain of custody keeps findings credible and usable if the situation later escalates.$q$),
('q4-113',4,'4.9','mcq',2,$q$Which log source would show a series of failed then successful authentication attempts on a specific Windows account?$q$,$q$["Security event log (event IDs 4625/4624)","Print spooler log","DHCP lease log","BIOS POST log"]$q$::jsonb,'0'::jsonb,$q$Windows Security event logs record logon failures (4625) and successes (4624) - the direct source for authentication-pattern analysis. The other logs cover unrelated subsystems.$q$),
('q4-114',4,'4.9','mcq',2,$q$A vulnerability scan report is itself considered what kind of data source during an investigation?$q$,$q$["Irrelevant to incident response","A log/data source showing pre-existing weaknesses that may explain how an intrusion succeeded","Only useful for compliance, never for IR","A replacement for all other logs"]$q$::jsonb,'1'::jsonb,$q$Scan reports document known weaknesses that may map directly to how an attacker gained entry, making them a valuable investigative data source alongside traditional logs.$q$),
('q4-115',4,'4.9','mcq',2,$q$Which log type would show that a specific application crashed repeatedly right before a service outage, independent of network or security logs?$q$,$q$["Application logs","VPN concentrator logs","Physical badge logs","DNS logs"]$q$::jsonb,'0'::jsonb,$q$Application logs record the software's own runtime events, including crashes - the direct source for diagnosing an app-level failure distinct from network or physical-access logs.$q$);
